input.content:
@font-face {
  font-family: "Inter";
  font-weight: 400;
  src: url("fonts/inter-latin-400-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Inter";
  font-weight: 500;
  src: url("fonts/inter-latin-500-normal.woff2") format("woff2");
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Inter", sans-serif;
  font-size: 15px;
  line-height: 1.55;
  color: #2b3236;
  background: #ffffff;
}

a {
  color: inherit;
}

/* Every band shares one centered column, so wide screens do not leave the content stuck to the left edge. */
.site-header,
.hero,
.points {
  max-width: 1120px;
  margin: 0 auto;
  padding-left: 64px;
  padding-right: 64px;
}

.site-header {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 12px 28px;
  padding-top: 22px;
  padding-bottom: 22px;
}

.logo {
  font-size: 18px;
  font-weight: 500;
  text-decoration: none;
}

.site-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 28px;
}

.site-nav a {
  text-decoration: none;
  color: #4d585e;
}

/* The hero holds the pitch on the left and the sample harbor page on the right. */
.hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 64px;
  align-items: center;
  padding-top: 72px;
  padding-bottom: 88px;
}

.hero-text {
  max-width: 440px;
}

h1 {
  margin: 0 0 16px;
  font-size: 34px;
  font-weight: 500;
  line-height: 1.2;
}

.hero-text p {
  margin: 0 0 28px;
  color: #4d585e;
}

.button {
  display: inline-block;
  padding: 12px 22px;
  border-radius: 6px;
  background: #1f5f7a;
  color: #ffffff;
  text-decoration: none;
  font-weight: 500;
}

.button:hover {
  background: #184d63;
}

.button:focus-visible,
.site-nav a:focus-visible,
.logo:focus-visible {
  outline: 2px solid #1f5f7a;
  outline-offset: 3px;
}

/* The tide table is shown as the page berth holders will see: a flat panel, no shadow. */
.today {
  padding: 28px 32px 24px;
  border: 1px solid #dfe5e8;
  border-radius: 8px;
  background: #f5f7f8;
}

h2 {
  margin: 0 0 14px;
  font-size: 18px;
  font-weight: 500;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 15px;
}

th,
td {
  padding: 10px 0;
  text-align: left;
  font-weight: 400;
  border-bottom: 1px solid #dfe5e8;
}

tbody tr:last-child td {
  border-bottom: none;
}

th {
  padding-top: 0;
  color: #4d585e;
}

/* Times and heights line up digit by digit and sit flush right, so they compare at a glance. */
td:nth-child(2),
td:nth-child(3),
th:nth-child(2),
th:nth-child(3) {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

td:nth-child(2),
td:nth-child(3) {
  font-weight: 500;
}

.points {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 48px;
  padding-bottom: 88px;
}

.point {
  padding-top: 20px;
  border-top: 1px solid #dfe5e8;
}

.point h3 {
  margin: 0 0 6px;
  font-size: 18px;
  font-weight: 500;
}

.point p {
  margin: 0;
  color: #4d585e;
}

/* Tablet: the hero stacks, and the three points stay side by side only while they have room. */
@media (max-width: 900px) {
  .hero {
    grid-template-columns: minmax(0, 1fr);
    gap: 40px;
    padding-top: 48px;
    padding-bottom: 64px;
  }

  .hero-text {
    max-width: 560px;
  }

  .today {
    max-width: 560px;
  }
}

@media (max-width: 760px) {
  .points {
    grid-template-columns: minmax(0, 1fr);
    gap: 32px;
    padding-bottom: 64px;
  }

  .point {
    max-width: 560px;
  }
}

/* Phone: tighter side margins and a smaller headline. */
@media (max-width: 480px) {
  .site-header,
  .hero,
  .points {
    padding-left: 20px;
    padding-right: 20px;
  }

  .site-nav {
    gap: 8px 20px;
  }

  h1 {
    font-size: 28px;
  }

  .today {
    padding: 20px 20px 16px;
  }
}

